package edu.evacuaid.api;

import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:evacuaid-test;DB_CLOSE_DELAY=-1") @AutoConfigureMockMvc class EvacuationApiIntegrationTest {
 @Autowired MockMvc mvc;
 @Test void sampleAndRouteEndpointsWork()throws Exception{String body=mvc.perform(post("/api/buildings/sample")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();var json=new com.fasterxml.jackson.databind.ObjectMapper().readTree(body);long id=json.path("id").asLong();mvc.perform(delete("/api/buildings/"+id+"/fire-scenario")).andExpect(status().isNoContent());mvc.perform(post("/api/buildings/"+id+"/route").contentType("application/json").content("{\"startCode\":\"LAB\",\"automaticExit\":true}")).andExpect(status().isOk()).andExpect(jsonPath("$[0].nodes[0]").value("LAB"));}
 @Test void fireOriginExcludesAffectedPassagesFromRoutes()throws Exception{String body=mvc.perform(post("/api/buildings/sample")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();long id=new com.fasterxml.jackson.databind.ObjectMapper().readTree(body).path("id").asLong();mvc.perform(post("/api/buildings/"+id+"/fire-scenario").contentType("application/json").content("{\"originCode\":\"J1\",\"startCode\":\"LAB\",\"automaticExit\":true,\"spreadSteps\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.hazardPassageCodes").isArray()).andExpect(jsonPath("$.routes").isEmpty());}
 @Test void routesCanConnectAcrossFloorsByStaircase()throws Exception{String body=mvc.perform(post("/api/buildings/sample")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();long id=new com.fasterxml.jackson.databind.ObjectMapper().readTree(body).path("id").asLong();mvc.perform(post("/api/buildings/"+id+"/route").contentType("application/json").content("{\"startCode\":\"F2-CLASS\",\"exitCode\":\"EXIT-A\",\"automaticExit\":false}")).andExpect(status().isOk()).andExpect(jsonPath("$[0].nodes").value(org.hamcrest.Matchers.hasItems("STAIR-2","STAIR-1","EXIT-A")));}
}
